/*
 * Standalone validation of the vendored UMASH reference implementation.
 *
 * Reproduces the OFFICIAL published test vector from the upstream README
 * (backtrace-labs/umash), which is generated by the repo's own example.c:
 *
 *     static const char my_secret[32] = "hello example.c";
 *     umash_params_derive(&my_params, 0, my_secret);
 *     seed = 42;  input = "the quick brown fox"
 *
 *     $ ./example "the quick brown fox"
 *     Fingerprint: 398c5bb5cc113d03, 3a52693519575aba
 *     Hash 0: 398c5bb5cc113d03
 *     Hash 1: 3a52693519575aba
 *
 * Build & run:
 *   clang -O3 -std=c11 -march=native selftest.c umash.c -o selftest && ./selftest
 */
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <inttypes.h>

#include "umash.h"

/* Exactly as in upstream example.c: 32-byte char array, zero-padded. */
static const char my_secret[32] = "hello example.c";

int
main(void)
{
	struct umash_params params;
	const char *input = "the quick brown fox";
	const uint64_t seed = 42;
	int rc = 0;

	umash_params_derive(&params, 0, my_secret);

	uint64_t h0 = umash_full(&params, seed, /*which=*/0, input, strlen(input));
	uint64_t h1 = umash_full(&params, seed, /*which=*/1, input, strlen(input));

	struct umash_fp fp = umash_fprint(&params, seed, input, strlen(input));

	const uint64_t exp0 = 0x398c5bb5cc113d03ULL;
	const uint64_t exp1 = 0x3a52693519575abaULL;

	printf("input           : \"%s\"  (seed=%" PRIu64 ")\n", input, seed);
	printf("umash_full w=0  : %016" PRIx64 "  expected %016" PRIx64 "  %s\n",
	    h0, exp0, h0 == exp0 ? "OK" : "MISMATCH");
	printf("umash_full w=1  : %016" PRIx64 "  expected %016" PRIx64 "  %s\n",
	    h1, exp1, h1 == exp1 ? "OK" : "MISMATCH");
	printf("umash_fprint[0] : %016" PRIx64 "  (must equal w=0)  %s\n",
	    fp.hash[0], fp.hash[0] == h0 ? "OK" : "MISMATCH");
	printf("umash_fprint[1] : %016" PRIx64 "  (must equal w=1)  %s\n",
	    fp.hash[1], fp.hash[1] == h1 ? "OK" : "MISMATCH");

	if (h0 != exp0 || h1 != exp1 || fp.hash[0] != h0 || fp.hash[1] != h1)
		rc = 1;

	/* A second independent length path: empty input still round-trips
	 * between umash_full(which=0) and umash_fprint[0]. */
	{
		uint64_t e0 = umash_full(&params, seed, 0, "", 0);
		struct umash_fp efp = umash_fprint(&params, seed, "", 0);
		printf("empty  w=0      : %016" PRIx64 "  fprint[0]=%016" PRIx64 "  %s\n",
		    e0, efp.hash[0], e0 == efp.hash[0] ? "OK" : "MISMATCH");
		if (e0 != efp.hash[0])
			rc = 1;
	}

	printf("\n%s\n", rc == 0 ? "SELFTEST PASSED" : "SELFTEST FAILED");
	return rc;
}
